package route

import (
	"encoding/json"
	"fmt"
	"io"
	"net/netip"
	"os"
	"strings"
)

type Config struct {
	DNSListen         string              `json:"dns_listen"`
	HTTPListen        string              `json:"http_listen"`
	Upstream          string              `json:"upstream"`
	Controller        string              `json:"controller"`
	ProxyGroup        string              `json:"proxy_group"`
	Mode              string              `json:"mode"`
	Judge             string              `json:"judge"`
	APIProxy          string              `json:"api_proxy"`
	Fallback          Decision            `json:"fallback"`
	PreflightMS       int                 `json:"preflight_ms"`
	DNSDeadlineMS     int                 `json:"dns_deadline_ms"`
	LearnedTTLSeconds int                 `json:"learned_ttl_seconds"`
	PublishIntervalSeconds int `json:"publish_interval_seconds"`
	Capacity          int                 `json:"capacity"`
	MaxAPIRequests    int                 `json:"max_api_requests"`
	Rules             []Rule              `json:"rules"`
	LabFixtures       map[string]Evidence `json:"lab_fixtures,omitempty"`
	Observation       *ObservationConfig  `json:"observation,omitempty"`
	Maintenance       *MaintenanceConfig  `json:"maintenance,omitempty"`
}

func LoadConfig(path string, allowLab bool) (Config, error) {
	f, err := os.Open(path)
	if err != nil {
		return Config{}, err
	}
	defer f.Close()
	c := Config{DNSListen: "127.0.0.1:15355", HTTPListen: "127.0.0.1:18765", Upstream: "127.0.0.1:15356", ProxyGroup: "PROXY", Mode: "off", Judge: "jev", Fallback: Direct, PreflightMS: 1500, DNSDeadlineMS: 2500, LearnedTTLSeconds: 604800, Capacity: 1024, MaxAPIRequests: 100, PublishIntervalSeconds: 30}
	d := json.NewDecoder(io.LimitReader(f, 1<<20))
	d.DisallowUnknownFields()
	if err = d.Decode(&c); err != nil {
		return Config{}, err
	}
	if d.Decode(&struct{}{}) != io.EOF {
		return Config{}, fmt.Errorf("trailing configuration data")
	}
	if c.Mode != "off" && c.Mode != "async" && c.Mode != "bounded-preflight" {
		return Config{}, fmt.Errorf("invalid mode")
	}
	if c.Judge != "jev" && c.Judge != "stub" {
		return Config{}, fmt.Errorf("invalid judge")
	}
	if (len(c.LabFixtures) > 0 || c.Judge == "stub") && !allowLab {
		return Config{}, fmt.Errorf("lab fixtures/stub require --allow-lab-fixtures")
	}
	if c.Fallback != Direct && c.Fallback != Proxy {
		return Config{}, fmt.Errorf("fallback must be DIRECT or PROXY")
	}
	if c.PublishIntervalSeconds < 1 || c.PublishIntervalSeconds > 3600 || c.PreflightMS < 50 || c.PreflightMS > 10000 || c.DNSDeadlineMS < c.PreflightMS+100 || c.DNSDeadlineMS > 15000 || c.LearnedTTLSeconds < 1 || c.Capacity < 1 || c.Capacity > 100000 || c.MaxAPIRequests < 1 {
		return Config{}, fmt.Errorf("invalid resource/deadline limits")
	}
	for _, address := range []*string{&c.DNSListen, &c.HTTPListen} {
		endpoint, e := netip.ParseAddrPort(*address)
		if e != nil || endpoint.Addr().String() != "127.0.0.1" || endpoint.Port() == 0 {
			return Config{}, fmt.Errorf("listeners must use 127.0.0.1 and a fixed port")
		}
		*address = endpoint.String()
	}
	if c.DNSListen == c.HTTPListen {
		return Config{}, fmt.Errorf("DNS and HTTP listeners must use different ports")
	}
	upstream, err := netip.ParseAddrPort(c.Upstream)
	if err != nil || upstream.Port() == 0 {
		return Config{}, fmt.Errorf("upstream must use an IP and a fixed port")
	}
	c.Upstream = netip.AddrPortFrom(upstream.Addr().Unmap(), upstream.Port()).String()
	if c.Upstream == c.DNSListen || c.Upstream == c.HTTPListen {
		return Config{}, fmt.Errorf("upstream must be an IP:port independent of Gate")
	}
	if err = validateController(c.Controller); err != nil {
		return Config{}, err
	}
	if _, err = parseAPIProxy(c.APIProxy); err != nil {
		return Config{}, err
	}
	if c.ProxyGroup == "" || strings.ContainsAny(c.ProxyGroup, ",\r\n") {
		return Config{}, fmt.Errorf("invalid proxy group")
	}
	if _, err = NewMatcher(c.Rules); err != nil {
		return Config{}, err
	}
	for host := range c.LabFixtures {
		d, err := Normalize(host)
		if err != nil || d.Host != host || !strings.HasSuffix(host, ".test") {
			return Config{}, fmt.Errorf("fixtures require normalized .test hostnames")
		}
	}
	if c.Observation != nil {
		if err := c.Observation.Validate(); err != nil {
			return Config{}, err
		}
	}
	if c.Maintenance != nil {
		if c.Mode != "async" || c.Observation == nil || len(c.LabFixtures) != 0 {
			return Config{}, fmt.Errorf("maintenance requires controlled async observation without lab fixtures")
		}
		if err := c.Maintenance.validate(); err != nil {
			return Config{}, err
		}
	}
	return c, nil
}

func Render(c Config) (map[string]any, error) {
	m, err := NewMatcher(c.Rules)
	if err != nil {
		return nil, err
	}
	providers := map[string]any{}
	for _, name := range []string{"learned-direct", "learned-proxy"} {
		providers[name] = map[string]any{"type": "http", "behavior": "classical", "format": "yaml", "url": "http://" + c.HTTPListen + "/rules/" + name + ".yaml", "path": "./route-agent/" + name + ".yaml", "interval": 3600}
	}
	return map[string]any{"dns": map[string]any{"enable": true, "enhanced-mode": "redir-host", "nameserver": []string{"udp://" + c.DNSListen}}, "rule-providers": providers, "rules": m.MihomoRules(c.ProxyGroup, c.Fallback)}, nil
}

package route

import (
	"bytes"
	"context"
	"crypto/rand"
	"crypto/sha256"
	"crypto/subtle"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"net/netip"
	"net/url"
	"os"
	"path/filepath"
	"runtime"
	"strconv"
	"time"
)

// Ownership pins one operator-owned app/core configuration generation. It is
// a cooperative lease, not a claim that Mihomo exposes an atomic reload epoch.
type Ownership struct {
	Version      int       `json:"version"`
	Controller   string    `json:"controller"`
	Listen       string    `json:"http_listen"`
	ProxyGroup   string    `json:"proxy_group"`
	ConfigPath   string    `json:"config_path"`
	ConfigSHA256 string    `json:"config_sha256"`
	RulesSHA256  string    `json:"rules_sha256"`
	Expires      time.Time `json:"expires_at"`
	Token        string    `json:"pause_token"`
	CorePID      int       `json:"core_pid"`
	CoreStarted  string    `json:"core_started_utc_ticks"`
}

type directPathChecker interface {
	Check(context.Context, netip.Addr) error
	CheckOwner(context.Context, Ownership) error
}
type windowsDirectPath struct{ index int }

type coreIdentity struct {
	PID     int    `json:"pid"`
	Started string `json:"started"`
}

func readCoreIdentity(ctx context.Context, controller string) (coreIdentity, error) {
	if runtime.GOOS != "windows" || controller == "" || validateController(controller) != nil {
		return coreIdentity{}, fmt.Errorf("publication blocked: core_process_identity_unavailable")
	}
	u, _ := url.Parse(controller)
	port, _ := strconv.Atoi(u.Port())
	identity, err := platformCoreIdentity(ctx, port)
	if err != nil {
		return coreIdentity{}, fmt.Errorf("publication blocked: core_process_identity_unavailable: %w", err)
	}
	return identity, nil
}

func (p windowsDirectPath) CheckOwner(ctx context.Context, lease Ownership) error {
	identity, err := readCoreIdentity(ctx, lease.Controller)
	if err != nil {
		return err
	}
	if identity.PID != lease.CorePID || identity.Started != lease.CoreStarted {
		return fmt.Errorf("publication blocked: core_process_restarted; new ownership required")
	}
	return nil
}

func (p windowsDirectPath) Check(ctx context.Context, target netip.Addr) error {
	if runtime.GOOS != "windows" || p.index < 1 || !target.IsValid() {
		return fmt.Errorf("publication blocked: direct_path_validation_unavailable")
	}
	// Only validated numeric values enter this read-only script. Do not constrain
	// Find-NetRoute to the requested interface: that could hide a preferred TUN.
	script := `$ErrorActionPreference='Stop'; $r=@(Find-NetRoute -RemoteIPAddress '` + target.String() + `'); $a=@(Get-NetAdapter -Physical -InterfaceIndex ` + strconv.Itoa(p.index) + `); if($r.Count -ne 2 -or $a.Count -ne 1 -or $a[0].Status -ne 'Up' -or @($r | Where-Object {$_.InterfaceIndex -ne ` + strconv.Itoa(p.index) + `}).Count -ne 0){exit 7}; 'physical_route_verified'`
	output, err := runWindowsQuery(ctx, "direct_path", script, 3*time.Second)
	if err != nil {
		return fmt.Errorf("publication blocked: selected_route_not_verified_physical: %w", err)
	}
	if string(output) != "physical_route_verified" {
		return fmt.Errorf("publication blocked: selected_route_not_verified_physical: %w", queryFailure("direct_path", "output_invalid", 0, false))
	}
	return nil
}

type publicationControl struct {
	path        string
	lease       Ownership
	checker     directPathChecker
	pause       chan chan error
	paused      bool                // worker-owned
	targets     map[netip.Addr]bool // worker-owned, bounded by the host budget
	maintenance *maintenanceWindow
	continuous  bool
	clock       func() time.Time // test clock; production uses wall time with lease checks
}

func digest(data []byte) string           { sum := sha256.Sum256(data); return hex.EncodeToString(sum[:]) }
func rulesDigest(rules []CoreRule) string { data, _ := json.Marshal(rules); return digest(data) }

func readPrivate(path string, limit int64) ([]byte, error) {
	file, err := os.Open(path)
	if err != nil {
		return nil, err
	}
	defer file.Close()
	data, err := io.ReadAll(io.LimitReader(file, limit+1))
	if err != nil || int64(len(data)) > limit {
		return nil, fmt.Errorf("invalid or oversized private file")
	}
	return data, nil
}

// PrepareOwnership reads the explicitly owned controller; it never changes it.
// The caller must keep this token-bearing artifact private and use a new path.
func PrepareOwnership(ctx context.Context, c Config, profilePath, secret string) (Ownership, error) {
	if profilePath == "" || secret == "" {
		return Ownership{}, fmt.Errorf("ownership requires an effective config file and controller authentication")
	}
	identity, err := readCoreIdentity(ctx, c.Controller)
	if err != nil {
		return Ownership{}, err
	}
	return prepareOwnership(ctx, c, profilePath, secret, identity)
}

func prepareOwnership(ctx context.Context, c Config, profilePath, secret string, identity coreIdentity) (Ownership, error) {
	if profilePath == "" || secret == "" {
		return Ownership{}, fmt.Errorf("ownership requires an effective config file and controller authentication")
	}
	profilePath, err := filepath.Abs(profilePath)
	if err != nil {
		return Ownership{}, err
	}
	data, err := readPrivate(profilePath, 4<<20)
	if err != nil {
		return Ownership{}, err
	}
	o, err := newObserver(c, Stub{})
	if err != nil {
		return Ownership{}, err
	}
	o.Providers.secret = secret
	rules, err := o.rules(ctx)
	if err != nil {
		return Ownership{}, err
	}
	after, err := readPrivate(profilePath, 4<<20)
	if err != nil || !bytes.Equal(data, after) {
		return Ownership{}, fmt.Errorf("effective config changed during ownership capture")
	}
	token := make([]byte, 32)
	if _, err = rand.Read(token); err != nil {
		return Ownership{}, err
	}
	return Ownership{Version: 1, Controller: c.Controller, Listen: c.HTTPListen, ProxyGroup: c.ProxyGroup, ConfigPath: profilePath, ConfigSHA256: digest(data), RulesSHA256: rulesDigest(rules), Expires: time.Now().Add(10 * time.Minute), Token: hex.EncodeToString(token), CorePID: identity.PID, CoreStarted: identity.Started}, nil
}

func NewControlledObserver(c Config, allowed bool, ownershipPath string, directInterface int, judge Judge, secret string) (*LabObserver, error) {
	return newControlledObserver(c, allowed, ownershipPath, windowsDirectPath{directInterface}, judge, secret)
}

func newControlledObserver(c Config, allowed bool, ownershipPath string, checker directPathChecker, judge Judge, secret string) (*LabObserver, error) {
	if !allowed || ownershipPath == "" || secret == "" || checker == nil {
		return nil, fmt.Errorf("controlled apply requires explicit --allow-controlled-apply, private ownership and controller authentication")
	}
	o, err := NewShadowObserver(c, true, judge, secret)
	if err != nil {
		return nil, err
	}
	lease, err := readOwnership(c, ownershipPath)
	if err != nil {
		return nil, err
	}
	o.control = &publicationControl{path: ownershipPath, lease: lease, checker: checker, pause: make(chan chan error, 1), targets: map[netip.Addr]bool{}}
	if err = o.control.check(); err != nil {
		return nil, err
	}
	o.publisher, err = newDecisionPublisher(c)
	if err != nil { return nil, err }
	o.shadow = false
	if c.Maintenance != nil {
		o.control.maintenance, err = newMaintenance(*c.Maintenance, time.Now())
		if err != nil {
			return nil, err
		}
		o.maintenanceState.Store("scheduled")
	}
	collector := o.collector.(*TLSCollector)
	collector.pathCheck = func(ctx context.Context, ip netip.Addr) error {
		if err := checker.Check(ctx, ip); err != nil {
			return err
		}
		o.control.targets[ip] = true
		return nil
	}
	// Verify ownership/snapshot before every provider PUT, including rollback.
	o.Providers.beforeWrite = func(ctx context.Context, entries map[string]Entry) error {
		if err := o.unchanged(ctx); err != nil {
			return err
		}
		if len(entries) > 0 {
			if o.control.maintenance.due(time.Now()) {
				return fmt.Errorf("publication blocked: maintenance drain due")
			}
			if err := o.control.check(); err != nil {
				return err
			}
			if err := o.control.checkPaths(ctx); err != nil {
				return err
			}
			if o.control.maintenance.due(time.Now()) {
				return fmt.Errorf("publication blocked: maintenance drain due")
			}
			for _, entry := range entries {
				if !time.Now().Before(entry.Expires) { return fmt.Errorf("publication blocked: decision expired before write") }
			}
			return ctx.Err()
		}
		return nil
	}
	return o, nil
}

func readOwnership(c Config, path string) (Ownership, error) {
	data, err := readPrivate(path, 16384)
	if err != nil {
		return Ownership{}, err
	}
	var lease Ownership
	decoder := json.NewDecoder(bytes.NewReader(data))
	decoder.DisallowUnknownFields()
	if decoder.Decode(&lease) != nil || decoder.Decode(&struct{}{}) != io.EOF || lease.Version != 1 || lease.Controller != c.Controller || lease.Listen != c.HTTPListen || lease.ProxyGroup != c.ProxyGroup || len(lease.Token) != 64 || len(lease.RulesSHA256) != 64 || len(lease.ConfigSHA256) != 64 {
		return Ownership{}, fmt.Errorf("invalid or differently owned publication lease")
	}
	if _, err := hex.DecodeString(lease.Token); err != nil || lease.CorePID < 1 || lease.CoreStarted == "" {
		return Ownership{}, fmt.Errorf("invalid pause token")
	}
	return lease, nil
}

func (p *publicationControl) checkPaths(ctx context.Context) error {
	for ip := range p.targets {
		if err := p.checker.Check(ctx, ip); err != nil {
			return err
		}
	}
	return nil
}

func (p *publicationControl) check() error {
	if !p.now().Before(p.lease.Expires) || p.lease.Expires.Sub(p.now()) > 10*time.Minute {
		return fmt.Errorf("publication blocked: ownership_expired_or_invalid")
	}
	return p.checkIdentity()
}

func (p *publicationControl) checkIdentity() error {
	data, err := readPrivate(p.path, 16384)
	var current Ownership
	if err != nil || json.Unmarshal(data, &current) != nil {
		return fmt.Errorf("publication blocked: ownership_unreadable")
	}
	if current.Expires.Equal(p.lease.Expires) {
		current.Expires = p.lease.Expires
	}
	if current != p.lease {
		return fmt.Errorf("publication blocked: ownership_changed; pause before profile refresh")
	}
	config, err := readPrivate(p.lease.ConfigPath, 4<<20)
	if err != nil || digest(config) != p.lease.ConfigSHA256 {
		return fmt.Errorf("publication blocked: effective_config_changed; new ownership required")
	}
	return nil
}

func (o *LabObserver) handlePause(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		w.WriteHeader(http.StatusMethodNotAllowed)
		return
	}
	if subtle.ConstantTimeCompare([]byte(r.Header.Get("Authorization")), []byte("Bearer "+o.control.lease.Token)) != 1 {
		w.WriteHeader(http.StatusUnauthorized)
		return
	}
	ack := make(chan error, 1)
	select {
	case o.control.pause <- ack:
	case <-r.Context().Done():
		return
	}
	select {
	case err := <-ack:
		if err != nil {
			http.Error(w, "pause cleanup failed; refresh is not authorized", http.StatusConflict)
			return
		}
		_ = json.NewEncoder(w).Encode(map[string]any{"paused": true, "owned_providers_empty": true, "new_ownership_required": true})
	case <-r.Context().Done():
	}
}

func (o *LabObserver) pauseControlled(ctx context.Context) error {
	if o.control.paused {
		return nil
	}
	if !o.ready.Load() {
		return fmt.Errorf("observer not ready")
	}
	if err := o.unchanged(ctx); err != nil {
		return err
	}
	if err := o.reconcile(ctx); err != nil {
		return err
	}
	if err := o.saveJournal("paused"); err != nil {
		return err
	}
	o.control.paused = true
	o.ready.Store(false)
	return nil
}

package route

import (
	"context"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"net/url"
	"sort"
	"strconv"
	"strings"
	"sync"
 "sync/atomic"
	"time"
)

type Entry struct {
	Decision Decision  `json:"decision"`
	Expires  time.Time `json:"expires_at"`
}

type Providers struct {
 nonemptySubmissions atomic.Uint64
 firstNonemptyMS atomic.Int64
	mu          sync.RWMutex
	writer      chan struct{}
	entries     map[string]Entry
	served      map[Decision][]byte
	dirty       bool
	generation  uint64
	controller  string
	secret      string
	client      *http.Client
	capacity    int
	prefix      string
	strictFetch bool
	fetched     map[Decision]uint64
	beforeWrite func(context.Context, map[string]Entry) error
}

func validateController(controller string) error {
	if controller != "" {
		u, err := url.Parse(controller)
		if err != nil || u.Scheme != "http" || u.Hostname() != "127.0.0.1" || u.User != nil || u.RawQuery != "" || u.ForceQuery || strings.Contains(controller, "#") || u.Path != "" {
			return fmt.Errorf("controller must be an http://127.0.0.1:PORT URL")
		}
		port, err := strconv.Atoi(u.Port())
		if err != nil || port < 1 || port > 65535 {
			return fmt.Errorf("controller must use a fixed port from 1 to 65535")
		}
	}
	return nil
}

func NewProviders(controller, secret string, capacity int) (*Providers, error) {
	return newProviders(controller, secret, capacity, "learned-")
}

func newProviders(controller, secret string, capacity int, prefix string) (*Providers, error) {
	if err := validateController(controller); err != nil {
		return nil, err
	}
	transport := http.DefaultTransport.(*http.Transport).Clone()
	transport.Proxy = nil
	p := &Providers{writer: make(chan struct{}, 1), entries: map[string]Entry{}, controller: controller, secret: secret, capacity: capacity, prefix: prefix,
		client: &http.Client{Transport: transport, CheckRedirect: func(*http.Request, []*http.Request) error { return http.ErrUseLastResponse }}}
	p.served = compile(p.entries)
	p.fetched = map[Decision]uint64{}
	p.dirty = controller != ""
	return p, nil
}

func compile(entries map[string]Entry) map[Decision][]byte {
	result := map[Decision][]byte{}
	for _, route := range []Decision{Direct, Proxy} {
		var hosts []string
		for host, entry := range entries {
			if entry.Decision == route {
				hosts = append(hosts, host)
			}
		}
		sort.Strings(hosts)
		// Mihomo's provider parser scans YAML lines; JSON-as-YAML is not accepted.
		// Values are already normalized hostnames, so this fixed format is sufficient.
		var body strings.Builder
		if len(hosts) == 0 {
			body.WriteString("payload: []\n")
		} else {
			body.WriteString("payload:\n")
			for _, host := range hosts {
				body.WriteString("  - DOMAIN," + host + "\n")
			}
		}
		result[route] = []byte(body.String())
	}
	return result
}

func (p *Providers) Handler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		w.WriteHeader(http.StatusMethodNotAllowed)
		return
	}
	var route Decision
	switch r.URL.Path {
	case "/rules/" + p.prefix + "direct.yaml":
		route = Direct
	case "/rules/" + p.prefix + "proxy.yaml":
		route = Proxy
	default:
		http.NotFound(w, r)
		return
	}
	p.mu.RLock()
	body := append([]byte(nil), p.served[route]...)
	p.mu.RUnlock()
	digest := sha256.Sum256(body)
	w.Header().Set("Content-Type", "application/yaml")
	w.Header().Set("ETag", `"`+hex.EncodeToString(digest[:])+`"`)
	w.Header().Set("Cache-Control", "no-store")
	if n, err := w.Write(body); err == nil && n == len(body) {
		p.mu.Lock()
		p.fetched[route]++
		p.mu.Unlock()
	}
}

func (p *Providers) Lookup(host string) (Entry, bool) {
	p.mu.RLock()
	defer p.mu.RUnlock()
	entry, ok := p.entries[host]
	return entry, ok && !p.dirty && time.Now().Before(entry.Expires)
}

func (p *Providers) Status() (uint64, int, bool) {
	p.mu.RLock()
	defer p.mu.RUnlock()
	return p.generation, len(p.entries), !p.dirty
}

func (p *Providers) updateCore(ctx context.Context, entries map[string]Entry) error {
	if p.controller == "" {
		return fmt.Errorf("controller is not configured")
	}
	for _, route := range []Decision{Direct, Proxy} {
		name := p.prefix + strings.ToLower(string(route))
		if p.beforeWrite != nil {
			if err := p.beforeWrite(ctx, entries); err != nil {
				return err
			}
		}
		p.mu.RLock()
		before := p.fetched[route]
		p.mu.RUnlock()
		req, _ := http.NewRequestWithContext(ctx, http.MethodPut, p.controller+"/providers/rules/"+name, nil)
		if p.secret != "" {
			req.Header.Set("Authorization", "Bearer "+p.secret)
		}
		for _, entry := range entries {
   if entry.Decision == route {
    p.nonemptySubmissions.Add(1)
    p.firstNonemptyMS.CompareAndSwap(0, time.Now().UnixMilli())
    break
   }
  }
		res, err := p.client.Do(req)
		if err != nil {
			return fmt.Errorf("provider reload transport failed")
		}
		_, _ = io.Copy(io.Discard, io.LimitReader(res.Body, 4096))
		res.Body.Close()
		if res.StatusCode != http.StatusNoContent {
			return fmt.Errorf("provider reload HTTP %d", res.StatusCode)
		}
		p.mu.RLock()
		fresh := p.fetched[route] > before
		p.mu.RUnlock()
		if p.strictFetch && !fresh {
			return fmt.Errorf("provider did not fetch this observer's payload during reload")
		}
	}
	return p.verifyCore(ctx, entries)
}

func (p *Providers) verifyCore(ctx context.Context, entries map[string]Entry) error {
	req, _ := http.NewRequestWithContext(ctx, http.MethodGet, p.controller+"/providers/rules", nil)
	if p.secret != "" {
		req.Header.Set("Authorization", "Bearer "+p.secret)
	}
	res, err := p.client.Do(req)
	if err != nil {
		return fmt.Errorf("provider readback failed")
	}
	defer res.Body.Close()
	if res.StatusCode != http.StatusOK {
		return fmt.Errorf("provider readback HTTP %d", res.StatusCode)
	}
	var metadata struct {
		Providers map[string]struct {
			Count    int    `json:"ruleCount"`
			Name     string `json:"name"`
			Behavior string `json:"behavior"`
			Vehicle  string `json:"vehicleType"`
		} `json:"providers"`
	}
	if json.NewDecoder(io.LimitReader(res.Body, 1<<20)).Decode(&metadata) != nil {
		return fmt.Errorf("invalid provider metadata")
	}
	counts := map[Decision]int{}
	for _, entry := range entries {
		counts[entry.Decision]++
	}
	for _, route := range []Decision{Direct, Proxy} {
		name := p.prefix + strings.ToLower(string(route))
		item, ok := metadata.Providers[name]
		if !ok || item.Count != counts[route] {
			return fmt.Errorf("provider count mismatch")
		}
		if p.strictFetch && (item.Name != name || item.Behavior != "Classical" || item.Vehicle != "HTTP") {
			return fmt.Errorf("provider identity metadata mismatch")
		}
	}
	return nil
}

// Check catches missing/reset providers without reloading an unchanged core.
// Matching counts alone do not prove content identity; successful commits still
// require PUT acknowledgements and subsequent connection auditing.
func (p *Providers) Check(ctx context.Context) error {
	select {
	case p.writer <- struct{}{}:
		defer func() { <-p.writer }()
	case <-ctx.Done():
		return ctx.Err()
	}
	p.mu.RLock()
	entries := p.entries
	p.mu.RUnlock()
	err := p.verifyCore(ctx, entries)
	if err != nil {
		p.mu.Lock()
		p.dirty = true
		p.mu.Unlock()
	}
	return err
}

// Change publishes a complete candidate snapshot. Only successful ACK/readback
// makes entries reusable. Failure restores the previous served/core snapshot.
func (p *Providers) Change(ctx context.Context, host string, entry *Entry) error {
	select {
	case p.writer <- struct{}{}:
		defer func() { <-p.writer }()
	case <-ctx.Done():
		return ctx.Err()
	}
	if err := ctx.Err(); err != nil {
		return err
	}
	p.mu.RLock()
	old := p.entries
	next := make(map[string]Entry, len(old)+1)
	for key, value := range old {
		if time.Now().Before(value.Expires) {
			next[key] = value
		}
	}
	p.mu.RUnlock()
	if host != "" {
		delete(next, host)
		if entry != nil {
			if entry.Decision != Direct && entry.Decision != Proxy {
				return fmt.Errorf("cannot compile UNCERTAIN")
			}
			d, err := Normalize(host)
			if err != nil || d.Host != host || d.Local {
				return fmt.Errorf("invalid learned hostname")
			}
			if len(next) >= p.capacity {
				return fmt.Errorf("learned capacity reached")
			}
			next[host] = *entry
		}
	}
	return p.commitSnapshot(ctx, old, next)
}

// Replace is a single serialized full snapshot transaction for the timed publisher.
func (p *Providers) Replace(ctx context.Context, entries map[string]Entry) error {
 select {
 case p.writer <- struct{}{}: defer func(){ <-p.writer }()
 case <-ctx.Done(): return ctx.Err()
 }
 if err := ctx.Err(); err != nil { return err }
 if len(entries) > p.capacity { return fmt.Errorf("learned capacity reached") }
 next := make(map[string]Entry, len(entries))
 for host, entry := range entries {
  d, err := Normalize(host)
  if err != nil || d.Host != host || d.Local || d.IP || (entry.Decision != Direct && entry.Decision != Proxy) || !time.Now().Before(entry.Expires) {
   return fmt.Errorf("invalid or expired learned result")
  }
  next[host] = entry
 }
 p.mu.RLock()
 old := p.entries
 p.mu.RUnlock()
 return p.commitSnapshot(ctx, old, next)
}

// Caller owns the writer token. Reuse the existing fresh-fetch/ACK/readback and rollback.
func (p *Providers) commitSnapshot(ctx context.Context, old, next map[string]Entry) error {
	p.mu.Lock()
	p.served = compile(next)
	p.dirty = true
	p.mu.Unlock()
	err := p.updateCore(ctx, next)
	if err != nil || ctx.Err() != nil {
		p.mu.Lock()
		p.served = compile(old)
		p.mu.Unlock()
		rollbackCtx, cancel := context.WithTimeout(context.Background(), time.Second)
		defer cancel()
		restored := p.updateCore(rollbackCtx, old) == nil
		p.mu.Lock()
		p.dirty = !restored
		p.mu.Unlock()
		if err != nil {
			return err
		}
		return ctx.Err()
	}
	p.mu.Lock()
	p.entries = next
	p.dirty = false
	p.generation++
	p.mu.Unlock()
	return nil
}

func (p *Providers) Expired() bool {
	p.mu.RLock()
	defer p.mu.RUnlock()
	for _, entry := range p.entries {
		if !time.Now().Before(entry.Expires) {
			return true
		}
	}
	return false
}

package route

import (
	"context"
	"encoding/json"
	"fmt"
	"io"
	"net"
	"net/http"
	"net/netip"
	"os"
	"reflect"
	"strings"
	"sync/atomic"
	"time"
)

type CoreRule struct {
	Index   int    `json:"index"`
	Type    string `json:"type"`
	Payload string `json:"payload"`
	Proxy   string `json:"proxy"`
	Extra   *struct {
		Disabled bool `json:"disabled"`
	} `json:"extra,omitempty"`
}

type CoreConnection struct {
	ID       string    `json:"id"`
	Start    time.Time `json:"start"`
	Rule     string    `json:"rule"`
	Payload  string    `json:"rulePayload"`
	Chains   []string  `json:"chains"`
	Metadata struct {
		Host            string `json:"host"`
		Network         string `json:"network"`
		DestinationPort string `json:"destinationPort"`
		DestinationIP   string `json:"destinationIP"`
		SpecialRules    string `json:"specialRules"`
		SpecialProxy    string `json:"specialProxy"`
		SniffHost       string `json:"sniffHost"`
	} `json:"metadata"`
}

// LabObserver shares one worker across lab, shadow and controlled modes.
// Run owns a single bounded worker; HTTP handlers only read atomic statistics.
type LabObserver struct {
	publisher        *decisionPublisher
	c                Config
	Providers        *Providers
	judge            Judge
	baseline         []CoreRule
	started          time.Time
	attempted        map[string]bool
	retryAfter       map[string]time.Time
	ready            atomic.Bool
	judgments        atomic.Uint64
	commits          atomic.Uint64
	failures         atomic.Uint64
	statePath        string
	shadow           bool
	collector        EvidenceCollector
	attempts         atomic.Uint64
	decisions        atomic.Uint64
	control          *publicationControl
	maintenanceState atomic.Value // string, read by HTTP without touching worker state
	lastEvaluation   atomic.Value // EvaluationDiagnostic; latest only, no hostname
}

func NewLabObserver(c Config, allowLab bool) (*LabObserver, error) {
	if !allowLab || c.Mode != "async" || c.Judge != "stub" || c.Controller == "" || len(c.LabFixtures) == 0 || len(c.LabFixtures) > 128 || len(c.LabFixtures) > c.Capacity {
		return nil, fmt.Errorf("observe-lab requires explicit lab permission, async/stub, isolated controller and 1..128 bounded synthetic fixtures")
	}
	for host := range c.LabFixtures {
		d, err := Normalize(host)
		if err != nil || d.Host != host || d.Local || d.IP || !strings.HasSuffix(host, ".test") {
			return nil, fmt.Errorf("observer fixtures must be normalized .test hostnames")
		}
	}
	return newObserver(c, Stub{Answer: Answer{Type: "choice", Choice: Proxy, Probabilities: map[Decision]float64{Direct: 0, Proxy: 1, Uncertain: 0}}})
}

func newObserver(c Config, judge Judge) (*LabObserver, error) {
	listen, err := netip.ParseAddrPort(c.HTTPListen)
	if err != nil || listen.Addr().String() != "127.0.0.1" || listen.Port() == 0 {
		return nil, fmt.Errorf("observer HTTP listener must use fixed loopback port")
	}
	p, err := newProviders(c.Controller, "", c.Capacity, "route-agent-tail-")
	if err != nil {
		return nil, err
	}
	return &LabObserver{c: c, Providers: p, attempted: map[string]bool{}, judge: judge}, nil
}

func (o *LabObserver) get(ctx context.Context, path string, value any) error {
	req, _ := http.NewRequestWithContext(ctx, http.MethodGet, o.c.Controller+path, nil)
	if o.Providers.secret != "" {
		req.Header.Set("Authorization", "Bearer "+o.Providers.secret)
	}
	res, err := o.Providers.client.Do(req)
	if err != nil {
		return fmt.Errorf("isolated observation request failed")
	}
	defer res.Body.Close()
	if res.StatusCode != http.StatusOK {
		return fmt.Errorf("isolated observation HTTP %d", res.StatusCode)
	}
	body, err := io.ReadAll(io.LimitReader(res.Body, (1<<20)+1))
	if err != nil || len(body) > 1<<20 || json.Unmarshal(body, value) != nil {
		return fmt.Errorf("invalid or oversized core observation")
	}
	return nil
}

func (o *LabObserver) rules(ctx context.Context) ([]CoreRule, error) {
	var config struct {
		Mode string `json:"mode"`
	}
	if err := o.get(ctx, "/configs", &config); err != nil {
		return nil, err
	}
	if config.Mode != "rule" {
		return nil, fmt.Errorf("isolated core must remain in rule mode")
	}
	var response struct {
		Rules []CoreRule `json:"rules"`
	}
	if err := o.get(ctx, "/rules", &response); err != nil {
		return nil, err
	}
	rules := response.Rules
	if len(rules) == 0 || !o.shadow && len(rules) < 3 {
		return nil, fmt.Errorf("missing tail rules")
	}
	for i, r := range rules {
		known := safeCategory(r.Type, "Domain DomainSuffix DomainKeyword DomainRegex IPCIDR SrcIPCIDR GeoIP GeoSite ProcessName ProcessPath ProcessNameRegex ProcessPathRegex RuleSet Network DstPort SrcPort InType InName Uid Match") != "OTHER"
		if len(rules) >= 3 && ((i == len(rules)-3 && r.Type == "AND" && r.Payload == tailCorePayload("route-agent-tail-direct") && r.Proxy == "DIRECT") || (i == len(rules)-2 && r.Type == "AND" && r.Payload == tailCorePayload("route-agent-tail-proxy") && r.Proxy == o.c.ProxyGroup)) {
			known = true
		}
		if !known || r.Index != i || r.Extra != nil && r.Extra.Disabled || i < len(rules)-1 && r.Type == "Match" {
			return nil, fmt.Errorf("ambiguous or disabled rule sequence")
		}
	}
	n := len(rules)
	if rules[n-1].Type != "Match" || rules[n-1].Payload != "" || rules[n-1].Proxy == "" {
		return nil, fmt.Errorf("missing unique terminal MATCH")
	}
	if !o.shadow && (rules[n-3].Type != "AND" || rules[n-3].Payload != tailCorePayload("route-agent-tail-direct") || rules[n-3].Proxy != "DIRECT" || rules[n-2].Type != "AND" || rules[n-2].Payload != tailCorePayload("route-agent-tail-proxy") || rules[n-2].Proxy != o.c.ProxyGroup) {
		return nil, fmt.Errorf("core does not have the expected final tail providers and unconditional MATCH")
	}
	return rules, nil
}

func (o *LabObserver) unchanged(ctx context.Context) error {
	if o.control != nil {
		if err := o.control.checkIdentity(); err != nil {
			return err
		}
		if err := o.control.checker.CheckOwner(ctx, o.control.lease); err != nil {
			return err
		}
	}
	rules, err := o.rules(ctx)
	if err != nil {
		return err
	}
	if !reflect.DeepEqual(o.baseline, rules) {
		return fmt.Errorf("core rule snapshot changed; stop isolated observer")
	}
	return nil
}

func fallbackHost(connection CoreConnection, since time.Time, fallback string) (Domain, bool) {
	if connection.Metadata.DestinationPort != "443" {
		return Domain{}, false
	}
	if connection.ID == "" || !connection.Start.After(since) || connection.Start.After(time.Now().Add(time.Second)) || connection.Rule != "Match" || connection.Payload != "" || len(connection.Chains) == 0 || connection.Chains[len(connection.Chains)-1] != fallback || connection.Metadata.Network != "tcp" || connection.Metadata.SpecialRules != "" || connection.Metadata.SpecialProxy != "" || connection.Metadata.SniffHost != "" {
		return Domain{}, false
	}
	d, err := Normalize(connection.Metadata.Host)
	return d, err == nil && !d.IP && !d.Local
}

func (o *LabObserver) poll(ctx context.Context) error {
	if err := o.unchanged(ctx); err != nil {
		return err
	}
	if o.control != nil {
		if err := o.control.check(); err != nil {
			return err
		}
		if err := o.control.checkPaths(ctx); err != nil {
			return err
		}
	}
	var snapshot struct {
		Connections []CoreConnection `json:"connections"`
	}
	if err := o.get(ctx, "/connections", &snapshot); err != nil {
		return err
	}
	for _, connection := range snapshot.Connections {
		d, ok := fallbackHost(connection, o.started, o.baseline[len(o.baseline)-1].Proxy)
		if !ok {
			continue
		}
		if o.attempted[d.Host] && (o.control == nil || !o.control.continuous || time.Now().Before(o.retryAfter[d.Host]) || !connection.Start.After(o.retryAfter[d.Host])) {
			continue
		}
		evidence, ok := o.c.LabFixtures[d.Host]
		if o.shadow || o.control != nil {
			ok = o.c.Observation.Allows(d.Host)
		}
		if !ok {
			continue
		}
		if o.attempts.Load() >= uint64(o.c.MaxAPIRequests) {
			break
		}
		o.attempted[d.Host] = true // bounded runs: once/host; continuous: fresh connection after cooldown
		if o.control != nil && o.control.continuous {
			if o.retryAfter == nil {
				o.retryAfter = map[string]time.Time{}
			}
			o.retryAfter[d.Host] = time.Now().Add(time.Minute)
		}
		o.attempts.Add(1)
		job, cancel := context.WithTimeout(ctx, time.Duration(o.c.PreflightMS)*time.Millisecond)
		err := o.evaluateAndPublish(job, d, evidence, connection.Metadata.DestinationIP, connection.ID)
		cancel()
		if err != nil {
			return err
		}
	}
	if !o.shadow && o.Providers.Expired() {
		if err := o.unchanged(ctx); err != nil {
			return err
		}
		if err := o.saveJournal("reconciling"); err != nil {
			return err
		}
		if err := o.Providers.Change(ctx, "", nil); err != nil {
			return err
		}
		if err := o.unchanged(ctx); err != nil {
			return err
		}
		if err := o.endDecisions("expired", true); err != nil { return err }
		return o.saveJournal("active")
	}
	return nil
}

func (o *LabObserver) evaluateAndPublish(job context.Context, d Domain, evidence Evidence, destinationIP string, sourceID ...string) (resultErr error) {
	started, deadline := time.Now(), remainingMS(job)
	scope := o.decisionScope()
	var result EvaluationResult
	var err error
	if o.collector != nil {
		result, err = EvaluateEvidenceDetailed(job, d.Host, o.collector, countedJudge{o})
		ip, parseErr := netip.ParseAddr(destinationIP)
		result.Diagnostic.ConnectionTargetMatch = parseErr == nil && result.target.IsValid() && ip.Unmap() == result.target
	} else {
		state := State{Hostname: d.Host, Registrable: d.Registrable, Evidence: evidence, Fixture: "synthetic_not_live_network_measurement"}
		answer, e := countedJudge{o}.Decide(job, state)
		err = e
		decision, reason := acceptWithReason(state, answer)
		choice := Uncertain
		if answer.Choice.Valid() {
			choice = answer.Choice
		}
		result.Diagnostic = EvaluationDiagnostic{Version: 1, Stage: "policy", StageError: "none", PolicyReason: reason, Decision: decision, Choice: choice, Evidence: evidence, DNS: "not_tested", ModelCalls: 1, Publication: "not_attempted", DeadlineMS: deadline, ModelMS: boundedMS(time.Since(started))}
	}
	r := &result.Diagnostic
	defer func() {
		r.JobDeadlineMS, r.JobElapsedMS = deadline, boundedMS(time.Since(started))
		if o.publisher != nil {
			id := ""
			if len(sourceID) > 0 { id = sourceID[0] }
			if e := o.recordDecision(job, d, *r, id, destinationIP, scope, started); e != nil && resultErr == nil { resultErr = e }
		}
		o.lastEvaluation.Store(*r)
	}()
	if err != nil && o.control != nil {
		o.failures.Add(1)
		return fmt.Errorf("publication blocked during evidence collection")
	}
	if o.shadow {
		if err != nil || job.Err() != nil {
			o.failures.Add(1)
		} else if r.Decision != Uncertain {
			if err = o.unchanged(job); err != nil {
				r.Stage, r.StageError = "ownership", stageError(job, "ownership_failed")
				return err
			}
			o.decisions.Add(1)
		}
		return nil
	}
	if o.publisher != nil && err == nil && job.Err() == nil && r.Decision != Uncertain {
  if e := o.unchanged(job); e != nil {
   r.Stage, r.StageError = "ownership", stageError(job, "ownership_failed")
   o.failures.Add(1)
   return e
  }
  o.decisions.Add(1)
  return nil // The judgment records pending work; it cannot publish.
 }
	if err == nil && job.Err() == nil && r.Decision != Uncertain {
		// One unchanged job deadline covers evaluation, identity, fetch, ACK and
		// readback. Timings do not extend it or authorize late writes.
		publicationStart := time.Now()
		r.Stage, r.Publication = "publication", "failed"
		defer func() {
			r.PublicationMS = boundedMS(time.Since(publicationStart))
			if resultErr != nil {
				r.StageError = stageError(job, "publication_failed")
			}
		}()
		if err = o.unchanged(job); err != nil {
			o.failures.Add(1)
			return err
		}
		if err = o.saveJournal("reconciling"); err != nil {
			return err
		}
		ttl := time.Duration(o.c.LearnedTTLSeconds) * time.Second
		if o.control != nil && ttl > time.Minute {
			ttl = time.Minute
		}
		err = o.Providers.Change(job, d.Host, &Entry{r.Decision, time.Now().Add(ttl)})
		if err == nil {
			err = o.unchanged(job)
		}
		if err != nil {
			o.failures.Add(1)
			return err
		}
		if err = o.saveJournal("active"); err != nil {
			return err
		}
		o.commits.Add(1)
		r.Publication = "committed"
	}
	if err != nil || job.Err() != nil {
		o.failures.Add(1)
		if job.Err() != nil {
			r.StageError = stageError(job, "evaluation_failed")
		}
	}
	return nil
}

func (o *LabObserver) HTTPHandler() http.Handler {
	mux := http.NewServeMux()
	if !o.shadow {
		mux.HandleFunc("/rules/", o.Providers.Handler)
	}
	if o.control != nil {
		mux.HandleFunc("/control/pause", o.handlePause)
	}
	mux.HandleFunc("/status", func(w http.ResponseWriter, r *http.Request) {
		if r.Method != http.MethodGet {
			w.WriteHeader(http.StatusMethodNotAllowed)
			return
		}
		_, count, ready := o.Providers.Status()
		if o.shadow {
			ready = o.ready.Load()
		}
		_ = json.NewEncoder(w).Encode(map[string]any{"lab_only": !o.shadow && o.control == nil, "controlled_apply": o.control != nil, "continuous": o.control != nil && o.control.continuous, "attempt_budget": o.c.MaxAPIRequests, "budget_exhausted": o.attempts.Load() >= uint64(o.c.MaxAPIRequests), "shadow": o.shadow, "attempts": o.attempts.Load(), "shadow_decisions": o.decisions.Load(), "observer_ready": o.ready.Load(), "core_ready": ready, "learned_count": count, "judge_calls": o.judgments.Load(), "commits": o.commits.Load(), "failures": o.failures.Load(), "maintenance": o.maintenanceState.Load(), "evaluation": o.lastEvaluation.Load(), "decisions": o.decisionReceipts(), "publication_schedule": o.publicationSchedule()})
	})
	return mux
}

// EvaluationDiagnostic returns a copy of the latest completed job only. It
// remains available after Run closes HTTP, including on a controlled failure.
func (o *LabObserver) EvaluationDiagnostic() *EvaluationDiagnostic {
	value := o.lastEvaluation.Load()
	if value == nil {
		return nil
	}
	diagnostic := value.(EvaluationDiagnostic)
	return &diagnostic
}

func (o *LabObserver) Run(ctx context.Context, statePath string) (runErr error) {
	cleanExit := false
	if !o.shadow && statePath == "" {
		return fmt.Errorf("publishing observer requires a private --state-file")
	}
	if o.control != nil {
		if err := o.control.check(); err != nil {
			return err
		}
		if err := o.control.checker.Check(ctx, netip.MustParseAddr("1.1.1.1")); err != nil {
			return err
		}
		lock, err := os.OpenFile(o.control.path+".lock", os.O_CREATE|os.O_EXCL|os.O_WRONLY, 0600)
		if err != nil {
			return fmt.Errorf("publication blocked: ownership_locked; recover explicitly after a crash")
		}
		defer func() {
			if cleanExit {
				_ = os.Remove(o.control.path + ".lock")
			}
		}()
		defer lock.Close()
		if err := json.NewEncoder(lock).Encode(publisherLock{Version: 1, PID: os.Getpid()}); err != nil {
			return err
		}
		if err := lock.Sync(); err != nil {
			return err
		}
	}
	listener, err := net.Listen("tcp", o.c.HTTPListen)
	if err != nil {
		return err
	}
	o.statePath = statePath
	o.Providers.strictFetch = true
	server := &http.Server{Handler: o.HTTPHandler(), ReadHeaderTimeout: time.Second, ReadTimeout: 2 * time.Second, WriteTimeout: 2 * time.Second, IdleTimeout: 10 * time.Second, MaxHeaderBytes: 16384}
	if o.control != nil {
		server.WriteTimeout = 25 * time.Second
	}
	defer server.Close()
	// Defer runs before closing HTTP so the owned core can fetch empty bodies.
	// A killed process cannot run this cleanup; the next startup reconciles.
	defer func() {
		if o.shadow {
			o.ready.Store(false)
			return
		}
		if !o.ready.Load() && (o.control == nil || !o.control.paused) {
			return
		}
		o.ready.Store(false)
		cleanupBudget := 2 * time.Second
		if o.control != nil {
			cleanupBudget = 10 * time.Second
		}
		cleanup, cancel := context.WithTimeout(context.Background(), cleanupBudget)
		defer cancel()
		err := o.unchanged(cleanup)
		if err == nil {
			err = o.reconcile(cleanup)
		}
		if err == nil {
			err = o.saveJournal("stopped")
		} else {
			_ = o.saveJournal("recovery_required")
		}
		if err != nil && runErr == nil {
			runErr = fmt.Errorf("observer exit cleanup incomplete; recovery required")
		}
		cleanExit = err == nil
	}()
	errors := make(chan error, 1)
	go func() { errors <- server.Serve(listener) }()
	// Core can fetch the initial empty providers during this bounded bootstrap.
	startup := time.Now().Add(10 * time.Second)
	tick := time.NewTicker(100 * time.Millisecond)
	defer tick.Stop()
	for {
		select {
		case <-ctx.Done():
			return nil
		case err := <-errors:
			return err
		case <-tick.C:
		}
		budget := time.Second
		if o.shadow || o.control != nil {
			budget = 10 * time.Second
		}
		job, cancel := context.WithTimeout(ctx, budget)
		if o.control != nil {
			if o.ready.Load() || o.control.paused {
				if err := o.renew(job); err != nil {
					cancel()
					return err
				}
			}
			select {
			case ack := <-o.control.pause:
				if o.control.maintenance != nil {
					o.control.maintenance.config.Resume = "manual"
				}
				err := o.pauseControlled(job)
				if err == nil && o.control.maintenance != nil {
					o.maintenanceState.Store("manual_pause")
				}
				ack <- err
				cancel()
				if err != nil {
					return err
				}
				continue
			default:
			}
			if o.ready.Load() || o.control.paused {
				if err := o.maintain(job, time.Now()); err != nil {
					o.maintenanceState.Store("blocked")
					cancel()
					return err
				}
			}
			if o.control.paused {
				cancel()
				continue
			}
		}
		if !o.ready.Load() {
			o.baseline, err = o.rules(job)
			if err == nil && o.control != nil && rulesDigest(o.baseline) != o.control.lease.RulesSHA256 {
				cancel()
				return fmt.Errorf("publication blocked: core_snapshot_does_not_match_ownership")
			}
			if err == nil && !o.shadow {
				if err = o.checkJournal(); err != nil {
					cancel()
					return err
				}
				err = o.reconcile(job)
			}
			if err == nil {
				o.started = time.Now()
				if o.publisher != nil { o.publisher.next = o.started.Add(o.publisher.interval); o.publisher.firstDueMS.Store(o.publisher.next.UnixMilli()) }
				o.ready.Store(true)
			}
			cancel()
			if err != nil && time.Now().After(startup) {
				return err
			}
			continue
		}
		if o.publisher != nil {
   // A fresh worker-tick context; no completed evaluation context authorizes this.
   if err := o.publishDue(job); err != nil { cancel(); if ctx.Err() != nil { return nil }; return err }
  }
		if o.control != nil && o.control.maintenance != nil {
			// Bound evidence collection at the next maintenance start. Provider
			// writes also check the clock, including a second PUT/rollback.
			bounded, stop := context.WithDeadline(job, o.control.maintenance.start)
			err = o.poll(bounded)
			stop()
		} else {
			err = o.poll(job)
		}
		cancel()
		if ctx.Err() != nil {
			return nil
		}
		if err != nil {
			if o.control != nil && o.control.maintenance.due(time.Now()) {
				continue // next worker tick drains; never starts another poll
			}
			return err
		}
	}
}

package route

import (
	"context"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"io"
	"os"
	"path/filepath"
)

// Restart deliberately evicts, never restores, these entries. The journal is
// durable lifecycle evidence, not authority to trust cached core rules.
type observerJournal struct {
	Version int              `json:"version"`
	Owner   string           `json:"owner"`
	Phase   string           `json:"phase"`
	Entries map[string]Entry `json:"entries"`
}

func (o *LabObserver) owner() string {
	body, _ := json.Marshal(struct {
		Controller, Listen string
		Rules              []CoreRule
	}{o.c.Controller, o.c.HTTPListen, o.baseline})
	digest := sha256.Sum256(body)
	return hex.EncodeToString(digest[:])
}

func (o *LabObserver) checkJournal() error {
	f, err := os.Open(o.statePath)
	if os.IsNotExist(err) {
		return nil
	}
	if err != nil {
		return fmt.Errorf("cannot open observer state")
	}
	defer f.Close()
	body, err := io.ReadAll(io.LimitReader(f, (1<<20)+1))
	var state observerJournal
	if err != nil || len(body) > 1<<20 || json.Unmarshal(body, &state) != nil || state.Version != 1 || state.Owner != o.owner() {
		return fmt.Errorf("invalid or differently owned observer state; recovery required")
	}
	return nil
}

func (o *LabObserver) saveJournal(phase string) error {
	if o.statePath == "" {
		return nil
	} // poll-only unit tests have no filesystem state
	o.Providers.mu.RLock()
	entries := make(map[string]Entry, len(o.Providers.entries))
	for host, entry := range o.Providers.entries {
		entries[host] = entry
	}
	o.Providers.mu.RUnlock()
	body, err := json.Marshal(observerJournal{1, o.owner(), phase, entries})
	if err != nil {
		return err
	}
	file, err := os.CreateTemp(filepath.Dir(o.statePath), ".observer-state-*")
	if err != nil {
		return fmt.Errorf("cannot create observer state temporary file")
	}
	name := file.Name()
	defer os.Remove(name)
	if _, err = file.Write(body); err == nil {
		err = file.Sync()
	}
	closeErr := file.Close()
	if err == nil {
		err = closeErr
	}
	if err == nil {
		err = os.Rename(name, o.statePath)
	}
	if err != nil {
		return fmt.Errorf("cannot replace observer state")
	}
	return nil
}

func (o *LabObserver) reconcile(ctx context.Context) error {
	if err := o.saveJournal("reconciling"); err != nil {
		return err
	}
	o.Providers.mu.Lock()
	o.Providers.entries = map[string]Entry{}
	o.Providers.dirty = true
	o.Providers.mu.Unlock()
	if err := o.Providers.Change(ctx, "", nil); err != nil {
		return err
	}
	if err := o.unchanged(ctx); err != nil {
		return err
	}
	if err := o.endDecisions("withdrawn", false); err != nil { return err }
	return o.saveJournal("active")
}

package route

import (
 "context"
 "crypto/rand"
 "encoding/hex"
 "encoding/json"
 "fmt"
 "os"
 "sync"
 "sync/atomic"
 "time"
)

const currentDecisionPolicy = "route-policy-v1"
const maxDecisionRecords = 4096

// Private append-only evidence. It never restores permission or rules on restart.
type DecisionRecord struct {
 ID string `json:"id"`
 ConnectionID string `json:"connection_id"`
 Host string `json:"hostname"`
 TargetIP string `json:"target_ip"`
 Started time.Time `json:"started_at"`
 Completed time.Time `json:"completed_at"`
 Expires time.Time `json:"expires_at"`
 Policy string `json:"policy_version"`
 Scope string `json:"scope"`
 Diagnostic EvaluationDiagnostic `json:"evaluation"`
 Adopted bool `json:"policy_adopted"`
 Status string `json:"status"`
 PublicationID string `json:"publication_id,omitempty"`
}

type decisionPublisher struct {
 firstDueMS atomic.Int64
 mu sync.RWMutex
 records []DecisionRecord
 session string
 next time.Time
 interval time.Duration
}

func randomDecisionID() (string, error) {
 var b [16]byte
 if _, err := rand.Read(b[:]); err != nil { return "", fmt.Errorf("decision identifier unavailable") }
 return hex.EncodeToString(b[:]), nil
}

func newDecisionPublisher(c Config) (*decisionPublisher, error) {
 seconds := c.PublishIntervalSeconds
 if seconds == 0 { seconds = 30 } // Also applies to programmatic constructors.
 if seconds < 1 || seconds > 3600 { return nil, fmt.Errorf("publish_interval_seconds must be 1..3600") }
 session, err := randomDecisionID()
 return &decisionPublisher{session:session, interval:time.Duration(seconds)*time.Second}, err
}

func (o *LabObserver) decisionScope() string {
 if o.control == nil { return "" }
 // Expiry may renew; immutable generation fields must not change.
 lease := o.control.lease
 lease.Expires = time.Time{}
 body, _ := json.Marshal(struct {
  Config Config
  Lease Ownership
  Rules []CoreRule
  Policy string
 }{o.c, lease, o.baseline, currentDecisionPolicy})
 return digest(body)
}

// Never log this private file or upload it. A new process starts with no records.
// A bounded ledger is intentionally not a database or a cross-session cache.
func (o *LabObserver) appendDecision(record DecisionRecord) error {
 if o.statePath == "" { return nil } // Unit tests without a lifecycle journal.
 path := o.statePath + ".decisions.jsonl"
 if info, err := os.Lstat(path); err == nil {
  if !info.Mode().IsRegular() || info.Size() >= 16<<20 { return fmt.Errorf("decision ledger limit or type invalid") }
 } else if !os.IsNotExist(err) { return fmt.Errorf("decision ledger unavailable") }
 body, err := json.Marshal(struct {
  Version int `json:"version"`
  Session string `json:"session"`
  Record DecisionRecord `json:"record"`
 }{1, o.publisher.session, record})
 if err != nil { return fmt.Errorf("decision encoding failed") }
 f, err := os.OpenFile(path, os.O_CREATE|os.O_APPEND|os.O_WRONLY, 0600)
 if err != nil { return fmt.Errorf("decision ledger unavailable") }
 body = append(body, '\n')
 n, writeErr := f.Write(body)
 if writeErr == nil && n != len(body) { writeErr = fmt.Errorf("short decision write") }
 if writeErr == nil { writeErr = f.Sync() }
 closeErr := f.Close()
 if writeErr != nil || closeErr != nil { return fmt.Errorf("decision ledger write failed") }
 return nil
}

func (o *LabObserver) recordDecision(ctx context.Context, d Domain, r EvaluationDiagnostic, connectionID, targetIP, scope string, started time.Time) error {
 p := o.publisher
 p.mu.Lock()
 defer p.mu.Unlock()
 if len(p.records) >= maxDecisionRecords { return fmt.Errorf("decision record capacity reached") }
 id, err := randomDecisionID()
 if err != nil { return err }
 ttl := time.Duration(o.c.LearnedTTLSeconds)*time.Second
 if ttl > time.Minute { ttl = time.Minute }
 rec := DecisionRecord{ID:id, ConnectionID:connectionID, Host:d.Host, TargetIP:targetIP,
  Started:started, Completed:time.Now(), Expires:started.Add(ttl), Policy:currentDecisionPolicy,
  Scope:scope, Diagnostic:r, Status:"rejected"}
 rec.Adopted = ctx.Err() == nil && r.StageError == "none" && r.PolicyReason == "accepted" && (r.Decision == Direct || r.Decision == Proxy)
 if rec.Adopted && time.Now().Before(rec.Expires) {
  rec.Status = "pending"
  // A second suggestion cannot extend an existing result without new publication.
  for _, old := range p.records {
   if old.Host == rec.Host && (old.Status == "pending" || old.Status == "applied") && time.Now().Before(old.Expires) && old.Scope == rec.Scope {
    rec.Status = "superseded"
    break
   }
  }
 }
 if err := o.appendDecision(rec); err != nil { return err }
 p.records = append(p.records, rec)
 return nil
}

func (o *LabObserver) decisionReceipts() []map[string]any {
 if o.publisher == nil { return nil }
 p := o.publisher
 p.mu.RLock()
 defer p.mu.RUnlock()
 out := make([]map[string]any, 0, len(p.records))
 for _, r := range p.records {
  out = append(out, map[string]any{"id":r.ID, "connection_id":r.ConnectionID,
   "choice":r.Diagnostic.Choice, "decision":r.Diagnostic.Decision,
   "policy_reason":r.Diagnostic.PolicyReason, "policy_adopted":r.Adopted,
   "status":r.Status, "expires_at":r.Expires, "policy_version":r.Policy,
   "scope":r.Scope, "publication_id":r.PublicationID})
 }
 return out
}

func (o *LabObserver) endDecisions(status string, expiredOnly bool) error {
 if o.publisher == nil { return nil }
 p := o.publisher
 p.mu.Lock()
 defer p.mu.Unlock()
 for i, r := range p.records {
  if (r.Status != "pending" && r.Status != "applied") || (expiredOnly && time.Now().Before(r.Expires)) { continue }
  r.Status = status
  if err := o.appendDecision(r); err != nil { return err }
  p.records[i] = r
 }
 return nil
}

// Called by the serial worker on its own tick context, never the judgment job.
// Initialization occurs only after empty bootstrap and current ownership checks.
func (o *LabObserver) publishDue(ctx context.Context) error {
 p := o.publisher
 if p == nil || p.next.IsZero() || time.Now().Before(p.next) { return nil }
 now := time.Now()
 p.next = p.next.Add((now.Sub(p.next)/p.interval + 1)*p.interval)
 if err := o.control.check(); err != nil { return err }
 if err := o.unchanged(ctx); err != nil { return err }
 if err := o.control.checkPaths(ctx); err != nil { return err }
 if o.control.paused || o.control.maintenance.due(time.Now()) { return nil }
 scope := o.decisionScope()
 next := map[string]Entry{}
 p.mu.Lock()
 defer p.mu.Unlock()
 for i, r := range p.records {
  if r.Status != "pending" && r.Status != "applied" { continue }
  status := r.Status
  if !time.Now().Before(r.Expires) { status = "expired" } else if !r.Adopted || r.Policy != currentDecisionPolicy || r.Scope != scope { status = "invalidated" }
  if status != r.Status {
   r.Status = status
   if err := o.appendDecision(r); err != nil { return err }
   p.records[i] = r
   continue
  }
  next[r.Host] = Entry{Decision:r.Diagnostic.Decision, Expires:r.Expires}
 }
 o.Providers.mu.RLock()
 same := len(o.Providers.entries) == len(next) && !o.Providers.dirty
 for host, entry := range next {
  old, ok := o.Providers.entries[host]
  if !ok || old.Decision != entry.Decision || !old.Expires.Equal(entry.Expires) { same = false }
 }
 o.Providers.mu.RUnlock()
 if same { return nil }
 if err := o.saveJournal("reconciling"); err != nil { return err }
 if err := o.Providers.Replace(ctx, next); err != nil {
  for i, r := range p.records {
   if r.Status == "pending" {
    r.Status = "failed"
    if persistErr := o.appendDecision(r); persistErr != nil { return persistErr }
    p.records[i] = r
   }
  }
  return err
 }
 if err := o.unchanged(ctx); err != nil { return err }
 if err := o.control.check(); err != nil { return err }
 if err := o.saveJournal("active"); err != nil { return err }
 generation, _, _ := o.Providers.Status()
 publicationID := fmt.Sprintf("%s-%d", p.session, generation)
 for i, r := range p.records {
  if r.Status == "pending" {
   r.Status, r.PublicationID = "applied", publicationID
   if err := o.appendDecision(r); err != nil { return err }
   p.records[i] = r
  }
 }
 o.commits.Add(1)
 return nil
}

func (o *LabObserver) publicationSchedule() map[string]any {
 if o.publisher == nil { return nil }
 return map[string]any{"interval_seconds":int(o.publisher.interval/time.Second),
  "first_due_unix_ms":o.publisher.firstDueMS.Load(),
  "first_nonempty_submission_unix_ms":o.Providers.firstNonemptyMS.Load(),
  "nonempty_submissions":o.Providers.nonemptySubmissions.Load()}
}

