	if runtime.GOOS != "windows" || os.Getenv("GITHUB_ACTIONS") != "true" || os.Getenv("RUNNER_ENVIRONMENT") != "github-hosted" || os.Getenv("GITHUB_REPOSITORY") != "Sonderjyf/mihomo-route-agent" || os.Getenv("OPENROUTER_API_KEY") != "" {
